+import fs from "fs";
+import path from "path";
+import { openCentralIndex, rebuildCentral } from "../core/index-db.js";
+import { aggregateRepositories } from "../core/aggregator.js";
+import type { RepositoryConfig } from "../core/aggregator.js";
+
+const main = async (): Promise<void> => {
+  const configPath = process.argv[2] || "repos.json";
+  const indexPath = process.argv[3] || ".commitlore-index.db";
+
+  if (!fs.existsSync(configPath)) {
+    console.error(`Config file not found: ${configPath}`);
+    console.error("Expected format:");
+    console.error(
+      JSON.stringify(
+        [
+          { name: "repo-1", path: "/path/to/repo1" },
+          { name: "repo-2", path: "/path/to/repo2" },
+        ],
+        null,
+        2
+      )
+    );
+    process.exit(1);
+  }
+
+  const repos: RepositoryConfig[] = JSON.parse(fs.readFileSync(configPath, "utf-8"));
+
+  console.log(`Aggregating ${repos.length} repositories...`);
+  const startTime = Date.now();
+
+  const records = aggregateRepositories(repos);
+
+  console.log(`Building central index at ${indexPath}...`);
+  const db = openCentralIndex(indexPath);
+  rebuildCentral(db, records);
+  db.close();
+
+  const duration = ((Date.now() - startTime) / 1000).toFixed(2);
+  console.log(`✓ Central index built successfully in ${duration}s`);
+  console.log(`  Records: ${records.length}`);
+  console.log(`  Repositories: ${repos.length}`);
+  console.log(`  Index size: ${(fs.statSync(indexPath).size / 1024).toFixed(2)} KB`);
+};
+
+main().catch((error) => {
+  console.error("Aggregation failed:", error);
+  process.exit(1);
+});
