+import { execSync } from "child_process";
+import Database from "better-sqlite3";
+import type { AggregatedRecordRow, RecordRow } from "./index-db.js";
+
+export interface RepositoryConfig {
+  name: string;
+  path: string;
+}
+
+export const scanRepository = (repoPath: string): RecordRow[] => {
+  try {
+    const output = execSync(
+      "git log --format='%h' --all | while read sha; do git show --format='%N' --no-patch $sha; done",
+      { cwd: repoPath, encoding: "utf-8" }
+    );
+
+    const records: RecordRow[] = [];
+    const noteLines = output.split("\n");
+    let currentSha = "";
+
+    const shaOutput = execSync("git log --format='%H' --all", { cwd: repoPath, encoding: "utf-8" });
+    const shas = shaOutput.split("\n").filter(Boolean);
+
+    const notesOutput = execSync("git show-ref --verify refs/notes/commitlore 2>/dev/null || true", {
+      cwd: repoPath,
+      encoding: "utf-8",
+    });
+
+    if (notesOutput.trim()) {
+      const shaToNotes = new Map<string, string>();
+      for (const sha of shas) {
+        try {
+          const notes = execSync(`git notes --ref=commitlore show ${sha} 2>/dev/null || true`, {
+            cwd: repoPath,
+            encoding: "utf-8",
+          }).trim();
+          if (notes) {
+            shaToNotes.set(sha, notes);
+          }
+        } catch {
+          // No notes for this commit
+        }
+      }
+
+      for (const [sha, notes] of shaToNotes) {
+        const trailers = notes.split("\n");
+        for (const trailer of trailers) {
+          if (trailer.trim()) {
+            records.push({
+              recordId: `${sha.slice(0, 7)}`,
+              sha: sha,
+              path: "",
+              trailer: trailer.trim(),
+            });
+          }
+        }
+      }
+    }
+
+    return records;
+  } catch (error) {
+    console.error(`Error scanning repository ${repoPath}:`, error);
+    return [];
+  }
+};
+
+export const aggregateRepositories = (repos: RepositoryConfig[]): AggregatedRecordRow[] => {
+  const allRecords: AggregatedRecordRow[] = [];
+
+  for (const repo of repos) {
+    console.log(`Scanning ${repo.name}...`);
+    const records = scanRepository(repo.path);
+    const aggregated = records.map((r) => ({
+      ...r,
+      repo: repo.name,
+    }));
+    allRecords.push(...aggregated);
+  }
+
+  console.log(`Total records collected: ${allRecords.length}`);
+  return allRecords;
+};
diff --git a/src/core/index-db.ts b/src/core/index-db.ts
index edcb0cb..30dbf31 100644
--- a/src/core/index-db.ts
+++ b/src/core/index-db.ts
@@ -7,12 +7,41 @@ export interface RecordRow {
   trailer: string;
 }

+export interface AggregatedRecordRow extends RecordRow {
+  repo: string;
+}
+
 export const openIndex = (gitDir: string): Database.Database =>
   new Database(`${gitDir}/commitlore/index.db`);

+export const openCentralIndex = (indexPath: string): Database.Database =>
+  new Database(indexPath);
+
 export const rebuild = (db: Database.Database, rows: readonly RecordRow[]): void => {
   db.exec("DROP TABLE IF EXISTS records");
   db.exec("CREATE TABLE records (record_id TEXT, sha TEXT, path TEXT, trailer TEXT)");
   const insert = db.prepare("INSERT INTO records VALUES (?, ?, ?, ?)");
   for (const row of rows) insert.run(row.recordId, row.sha, row.path, row.trailer);
 };
+
+export const rebuildCentral = (db: Database.Database, rows: readonly AggregatedRecordRow[]): void => {
+  db.exec("DROP TABLE IF EXISTS records");
+  db.exec("CREATE TABLE records (repo TEXT, record_id TEXT, sha TEXT, path TEXT, trailer TEXT)");
+  db.exec("CREATE INDEX idx_repo ON records(repo)");
+  db.exec("CREATE INDEX idx_trailer ON records(trailer)");
+  db.exec("CREATE INDEX idx_record_id ON records(record_id)");
+  const insert = db.prepare("INSERT INTO records VALUES (?, ?, ?, ?, ?)");
+  for (const row of rows) insert.run(row.repo, row.recordId, row.sha, row.path, row.trailer);
+};
+
+export const queryRecords = (db: Database.Database, query?: string): AggregatedRecordRow[] => {
+  let sql = "SELECT repo, record_id as recordId, sha, path, trailer FROM records";
+  const params: unknown[] = [];
+
+  if (query) {
+    sql += " WHERE trailer LIKE ?";
+    params.push(`%${query}%`);
+  }
+
+  return db.prepare(sql).all(...params) as AggregatedRecordRow[];
+};
